import os,time,json,hmac,hashlib,base64,uuid
import bcrypt,httpx
from fastapi import FastAPI,Request,HTTPException
from fastapi.responses import HTMLResponse,JSONResponse
app=FastAPI()
URL=(os.getenv("ALGORITM_SUPABASE_URL") or os.getenv("SUPABASE_URL") or "").rstrip("/")
KEY=os.getenv("SUPABASE_SERVICE_ROLE_KEY") or os.getenv("ALGORITM_SUPABASE_KEY") or os.getenv("SUPABASE_SECRET_KEY") or ""
SECRET=os.getenv("ADMIN_SESSION_SECRET") or KEY or "change-this-admin-secret"
TABLES={"courses","students","groups","study_groups","enrollments","payments","online_payment_requests","attendance","online_tests","test_questions","test_results","site_settings"}
async def db(method,path,data=None,prefer=None):
 if not URL or not KEY: raise HTTPException(503,"Supabase sozlamalari topilmadi")
 headers={"apikey":KEY,"Authorization":"Bearer "+KEY,"Content-Type":"application/json"}
 if prefer:headers["Prefer"]=prefer
 async with httpx.AsyncClient(timeout=25) as c:r=await c.request(method,URL+"/rest/v1/"+path,headers=headers,json=data)
 if r.status_code>=400:raise HTTPException(r.status_code,"Database: "+r.text[:250])
 return r.json() if r.content else []
def token(p):
 x=base64.urlsafe_b64encode(json.dumps(p).encode()).decode().rstrip("=")
 return x+"."+hmac.new(SECRET.encode(),x.encode(),hashlib.sha256).hexdigest()
def admin(r):
 try:
  x,s=r.cookies.get("alg_admin","").rsplit(".",1)
  if not hmac.compare_digest(s,hmac.new(SECRET.encode(),x.encode(),hashlib.sha256).hexdigest()):return False
  return json.loads(base64.urlsafe_b64decode(x+"="*((4-len(x)%4)%4))).get("exp",0)>time.time()
 except:return False
def guard(r):
 if not admin(r):raise HTTPException(401,"Admin tizimiga qayta kiring")
@app.get("/api/health")
async def health():return {"ok":True,"database_configured":bool(URL and KEY)}
@app.get("/api/courses")
async def courses():return await db("GET","courses?select=id,name,price,description,teacher_name,teacher_bio,image_path,teacher_image,is_active&is_active=eq.true&order=id")
@app.post("/api/register")
async def register(r:Request):
 d=await r.json()
 if not all(str(d.get(k,"")).strip() for k in ("full_name","phone","course_id")):raise HTTPException(400,"Ism, telefon va kursni kiriting")
 return await db("POST","students",{"full_name":str(d["full_name"]).strip(),"phone":str(d["phone"]).strip(),"course_id":int(d["course_id"]),"note":str(d.get("note","")),"status":"new"},"return=representation")
@app.post("/api/admin/login")
async def login(r:Request):
 d=await r.json();u=str(d.get("username","")).strip();p=str(d.get("password",""))
 if not u or not p:raise HTTPException(400,"Login va parolni kiriting")
 rows=await db("GET","admins?select=id,username,password_hash&username=eq."+httpx.QueryParams({"u":u})["u"]+"&limit=1")
 if not rows:raise HTTPException(401,"Login yoki parol noto‘g‘ri")
 try:ok=bcrypt.checkpw(p.encode(),rows[0]["password_hash"].encode())
 except Exception:ok=False
 if not ok:raise HTTPException(401,"Login yoki parol noto‘g‘ri")
 out=JSONResponse({"ok":True});out.set_cookie("alg_admin",token({"id":rows[0]["id"],"exp":time.time()+43200}),httponly=True,secure=True,samesite="lax",max_age=43200);return out
@app.post("/api/admin/logout")
async def logout():
 out=JSONResponse({"ok":True});out.delete_cookie("alg_admin");return out
@app.get("/api/admin/{table}")
async def list_rows(table:str,r:Request):
 guard(r)
 table="study_groups" if table=="groups" else table
 if table not in TABLES:raise HTTPException(404,"Jadval topilmadi")
 sel={"students":"*,courses(name)","payments":"*,students(full_name)","study_groups":"*,courses(name)","online_payment_requests":"*,courses(name)"}.get(table,"*")
 order="" if table=="site_settings" else "&order=id.desc"
 return await db("GET",table+"?select="+sel+order)
@app.post("/api/admin/{table}")
async def create_row(table:str,r:Request):
 guard(r)
 table="study_groups" if table=="groups" else table
 if table not in TABLES:raise HTTPException(404,"Jadval topilmadi")
 return await db("POST",table,await r.json(),"return=representation")
@app.patch("/api/admin/{table}/{rid}")
async def update_row(table:str,rid:str,r:Request):
 guard(r)
 if table=="site_settings":
  return await db("PATCH","site_settings?setting_key=eq."+httpx.QueryParams({"k":rid})["k"],await r.json(),"return=representation")
 table="study_groups" if table=="groups" else table
 if table not in TABLES:raise HTTPException(404,"Jadval topilmadi")
 return await db("PATCH",table+"?id=eq."+rid,await r.json(),"return=representation")
@app.delete("/api/admin/{table}/{rid}")
async def delete_row(table:str,rid:str,r:Request):
 guard(r)
 table="study_groups" if table=="groups" else table
 if table not in TABLES:raise HTTPException(404,"Jadval topilmadi")
 return await db("DELETE",table+"?id=eq."+rid)
@app.get("/api/site-settings")
async def public_site_settings():
 rows=await db("GET","site_settings?select=setting_key,setting_value")
 allowed={"hero_title","hero_text","about_title","about_text","phone","email","address","card_number_1","card_number_2","card_number_3","card_holder_1","card_holder_2","card_holder_3"}
 return {x["setting_key"]:x.get("setting_value") for x in rows if x.get("setting_key") in allowed}

@app.post("/api/admin/site-settings")
async def save_site_settings(r:Request):
 guard(r)
 data=await r.json()
 if not isinstance(data,dict):raise HTTPException(400,"Sozlamalar formati noto‘g‘ri")
 allowed={"hero_title","hero_text","about_title","about_text","phone","email","address","card_number_1","card_number_2","card_number_3","card_holder_1","card_holder_2","card_holder_3"}
 saved=[]
 for k,v in data.items():
  if k in allowed:
   saved.extend(await db("POST","site_settings?on_conflict=setting_key",{"setting_key":k,"setting_value":str(v or "")},"resolution=merge-duplicates,return=representation"))
 return {"ok":True,"saved":len(saved)}

@app.post("/api/payment-requests")
async def create_payment_request(r:Request):
 d=await r.json()
 required=("full_name","phone","course_id","amount","receipt_base64","receipt_name")
 if not all(str(d.get(k,"")).strip() for k in required):raise HTTPException(400,"Barcha to‘lov ma’lumotlarini kiriting va chekni yuklang")
 try:
  raw=base64.b64decode(d["receipt_base64"],validate=True)
  course_id=int(d["course_id"]);amount=float(d["amount"])
  if amount<=0:raise HTTPException(400,"To‘lov summasi noldan katta bo‘lishi kerak")
 except Exception:raise HTTPException(400,"To‘lov ma’lumotlari noto‘g‘ri")
 if not raw or len(raw)>5*1024*1024:raise HTTPException(400,"Chek 5 MB dan kichik bo‘lishi kerak")
 ext=str(d["receipt_name"]).lower().rsplit(".",1)[-1]
 if ext not in {"jpg","jpeg","png","webp","pdf"}:raise HTTPException(400,"Chek JPG, PNG, WEBP yoki PDF bo‘lishi kerak")
 path=str(uuid.uuid4())+"."+ext
 content_type={"jpg":"image/jpeg","jpeg":"image/jpeg","png":"image/png","webp":"image/webp","pdf":"application/pdf"}[ext]
 headers={"apikey":KEY,"Authorization":"Bearer "+KEY,"Content-Type":content_type,"x-upsert":"false"}
 async with httpx.AsyncClient(timeout=30) as c:
  upload=await c.post(URL+"/storage/v1/object/payment-receipts/"+path,headers=headers,content=raw)
 if upload.status_code>=300:raise HTTPException(502,"Chekni saqlashda xatolik: "+upload.text[:160])
 try:
  rows=await db("POST","online_payment_requests",{"full_name":str(d["full_name"]).strip(),"phone":str(d["phone"]).strip(),"course_id":course_id,"amount":amount,"provider":"bank","receipt_path":path,"payer_card_last4":str(d.get("payer_card_last4",""))[-4:],"status":"pending"},"return=representation")
 except Exception:
  async with httpx.AsyncClient(timeout=15) as c:await c.delete(URL+"/storage/v1/object/payment-receipts/"+path,headers={"apikey":KEY,"Authorization":"Bearer "+KEY})
  raise
 return {"ok":True,"request":rows[0] if rows else {}}

@app.post("/api/admin/payment-receipt-url")
async def payment_receipt_url(r:Request):
 guard(r)
 d=await r.json();path=str(d.get("path","")).replace("..","").lstrip("/")
 if not path:raise HTTPException(400,"Chek manzili topilmadi")
 headers={"apikey":KEY,"Authorization":"Bearer "+KEY,"Content-Type":"application/json"}
 async with httpx.AsyncClient(timeout=20) as c:resp=await c.post(URL+"/storage/v1/object/sign/payment-receipts/"+path,headers=headers,json={"expiresIn":3600})
 if resp.status_code>=300:raise HTTPException(502,"Chek havolasini yaratib bo‘lmadi")
 return {"url":URL+"/storage/v1"+resp.json().get("signedURL","")}

@app.get("/{path:path}",response_class=HTMLResponse)
async def page(path:str=""):return HTML
